import ch.jalu.configme.configurationdata.CommentsConfiguration;
import org.junit.Assert;
import org.junit.Test;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test
    public void commentsConfigurationConstructorWithNoArgsTest() {
        // When
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

        // Then
        Assert.assertTrue(commentsConfiguration.getAllComments().isEmpty());
    }

    @Test
    public void commentsConfigurationConstructorWithMapArgsTest() {
        // Given
        Map<String, List<String>> commentMap = new HashMap<>();
        commentMap.put("Path1", Arrays.asList("Comment1"));

        // When
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(commentMap);

        // Then
        Assert.assertEquals(1, commentsConfiguration.getAllComments().size());
    }

    @Test
    public void setCommentTest() {
        // Given
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

        // When
        commentsConfiguration.setComment("NewPath", "New comment");

        // Then
        Assert.assertEquals(1, commentsConfiguration.getAllComments().size());
        Assert.assertEquals("New comment", commentsConfiguration.getAllComments().get("NewPath").get(0));
    }

    @Test
    public void getAllCommentsTest() {
        // Given
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment("Path1", "Comment1");

        // When
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();

        // Then
        Assert.assertEquals(1, allComments.size());
        Assert.assertEquals("Comment1", allComments.get("Path1").get(0));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void getAllCommentsImmutableTest() {
        // Given
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment("Path1", "Comment1");

        // When
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();

        // Then
        allComments.put("New key", Arrays.asList("New value")); // should throw exception
    }
}
